INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_748d26e760e54651eaa0d8', 'ZM session stability gate', 'leonard.hayes@harmonygames.co', '["julia.lawson@harmonygames.co", "robert@harmonygames.co", "brian.foster@harmonygames.co", "vincent.parker@harmonygames.co"]', 'private', E'ZM session stability gate\nSep 24\n\nFriend sessions only help us if the game held up on the player''s phone and they played a build a real player gets.\n\nDevices\nSamsung is the one device group we check here: the Galaxy S, A and Z phones, which also show up as model numbers like SM-S, SM-A and SM-F. Other phones need nothing.\nA Samsung session counts once we have a clean pass covering that device. A pass covers a device only if it ran on that device. A closed ticket isn''t a pass. Once there is a pass, it covers all the Samsung sessions in the read.\nZOM-559 stays in the bug queue as usual. We aren''t waiting on it for this.\n\nPasses\nArthur Blake owns the Vision Bot job and says what a pass does and doesn''t cover.\n\nBuilds\nSessions on dev builds do not count. A dev build is anything that never went through a store.\n\nThese rules apply to every session in the read, whatever day it ran.\n\nLeonard\n\nUpdate Sep 30: Arthur opened his Vision Bot PR today. What a pass covers gets discussed there.', '[{"start": 0, "end": 26, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 26, "end": 992, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'c4e19b7a02', 'f_748d26e760e54651eaa0d8', '2025-09-24T15:12:40Z', '2025-09-30T19:21:44Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_c691d577b8f837eb4f9eaa', 'ZM sessions log note', 'julia.lawson@harmonygames.co', '["leonard.hayes@harmonygames.co", "robert@harmonygames.co"]', 'private', E'ZM sessions log note\n\nWhy tickets: Leonard wants the friend sessions tracked one by one so the read can be closed out properly, and the observers'' forms are spread over mail and Docs. So each session gets a ZOM ticket, and the workbook log has a row per ticket.\n\nI''m typing the tickets up in one batch today. Each ticket transcribes a dated observer form, so it carries the form date and the session date. The ticket date is just the day I typed it.\n\nThe phone goes in a comment on the ticket. Build, age and relation stay in the observer''s notes doc.\n\nClose-out when the read is done: counted goes to Done, not counted goes to Canceled.\n\nJulia', '[{"start": 0, "end": 21, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 21, "end": 644, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'ba438f6bc8', 'f_c691d577b8f837eb4f9eaa', '2025-09-30T16:24:03Z', '2025-09-30T16:35:20Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
