VALUES ('f_a087f049d271e9aa9f567f', 'slide_29241137200c', 'el_18102c1d9b66', 'TEXT_BOX', E'Labels\nThe observer''s label stands, nothing gets re-derived.\nOne label per session: casual or RPG.', NULL, 0, 0, 9144000, 5143500, NULL, 0);
