VALUES ('f_a087f049d271e9aa9f567f', 'slide_1b64c7b03a47', 'el_5b5d50499cb5', 'TEXT_BOX', E'The lead\nThe lead is the higher mean star rating over counted sessions.\nAt least 6 counted sessions per audience.\nA gap under 0.25 is no clear lead.\nSessions decide. Panel and other numbers are context.', NULL, 0, 0, 9144000, 5143500, NULL, 0);
