INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('julia.lawson@harmonygames.co/<CA9cfc392aa3b0ae856cc7f3b86c0d50e6f144@mail.gmail.com>', 'julia.lawson@harmonygames.co/1843954918097449014', 'julia.lawson@harmonygames.co', '["INBOX", "IMPORTANT", "CATEGORY_PERSONAL"]', 'Julia, stars per player from the two runs (puzzlesvszombies-3 and -4). The mails only link the videos and the survey reports, so I pulled th', 1758532446000, '2025-09-22T09:14:06Z', 1538, 'Fwd: Playtest results for Puzzles vs. Zombies', 'leonard.hayes@harmonygames.co', 'Leonard Hayes', '["Julia Lawson <julia.lawson@harmonygames.co>"]', '[]', '[]', '[]', E'Julia, stars per player from the two runs (puzzlesvszombies-3 and -4). The mails only link the videos and the survey reports, so I pulled these from the reports.\r\n\r\niOS run: player 1 3.5, player 2 3, player 3 3.5, player 4 4, player 5 3\r\nAndroid run: player 6 3, player 7 3.5, player 8 1, player 9 3, player 10 3.5\r\n\r\nPlayer 8''s rating is void: the app froze on them and they rated the freeze, not the game.\r\n\r\n---------- Forwarded message ---------\r\nFrom: SVC_2646_NAME <SVC_2646_EMAIL>\r\nDate: Mon, Sep 22, 2025 at 03:44 UTC\r\nSubject: Playtest results for Puzzles vs. Zombies\r\nTo: Leonard Hayes <leonard.hayes@harmonygames.co>\r\n\r\nHi Leonard,\r\n\r\nHere are the latest player videos of Puzzles vs. Zombies:\r\n\r\nYou can watch them on https://app.Playtestcloud.com/playtests/puzzlesvszombies-3\r\n\r\nYou can also use this private link to give people inside your team access to the videos without having to sign in: https://app.Playtestcloud.com/share?public_mode=false\r\n\r\nWe’ve prepared a report of the survey responses in this playtest that you can access here: https://app.Playtestcloud.com/playtests/puzzlesvszombies-3/report.\r\n\r\nWe hope that these videos are full of insights for you. We would also appreciate if you could let us know how we‘re doing by rating Playtestcloud here. Feel free to contact us if There are any questions!\r\n\r\nBest,\r\nTeam Playtestcloud\r\n\r\nP.S.: We’re currently still preparing the automated transcripts you ordered.\r\nThe transcripts will automatically show up next to the videos once they’re ready.\r\n\r\nLeonard', NULL, '[{"name": "Message-ID", "value": "<CA9cfc392aa3b0ae856cc7f3b86c0d50e6f144@mail.gmail.com>"}, {"name": "Date", "value": "Mon, 22 Sep 2025 09:14:06 +0000"}, {"name": "Subject", "value": "Fwd: Playtest results for Puzzles vs. Zombies"}, {"name": "From", "value": "Leonard Hayes <leonard.hayes@harmonygames.co>"}, {"name": "To", "value": "Julia Lawson <julia.lawson@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
