INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('julia.lawson@harmonygames.co/<CA627c4f3eb036ebf28f00ed982586b0cba3e5@mail.gmail.com>', 'julia.lawson@harmonygames.co/1844592159752803121', 'julia.lawson@harmonygames.co', '["INBOX", "IMPORTANT", "CATEGORY_PERSONAL"]', 'Hey Julia, How is the level work going? I keep missing you on Slack, last week was all items for me. Something has been on my mind about Fri', 1759140167000, '2025-09-29T10:02:47Z', 557, 'a small thing from Friday', 'claire.morgan@harmonygames.co', 'Claire Morgan', '["Julia Lawson <julia.lawson@harmonygames.co>"]', '[]', '[]', '[]', E'Hey Julia,\r\n\r\nHow is the level work going? I keep missing you on Slack, last week was all items for me.\r\n\r\nSomething has been on my mind about Friday at my place. Before anyone touched their phone I sat them all down and took them through how ZM plays: what the cards do, which items to grab first, when to save the grenades for the big monsters. I didn''t want them stuck and bored, and I know that''s not what Leonard asked for. So if they looked like they knew what they were doing from the first level, that''s why.\r\n\r\nBetter you hear it from me.\r\n\r\nClaire', NULL, '[{"name": "Message-ID", "value": "<CA627c4f3eb036ebf28f00ed982586b0cba3e5@mail.gmail.com>"}, {"name": "Date", "value": "Mon, 29 Sep 2025 10:02:47 +0000"}, {"name": "Subject", "value": "a small thing from Friday"}, {"name": "From", "value": "Claire Morgan <claire.morgan@harmonygames.co>"}, {"name": "To", "value": "Julia Lawson <julia.lawson@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
