VALUES ('68dc0acf1815df76ed9b887d', 'Cards earlier: waiting on the audience read', '6851a6569f3bf818760632ab', '68c451221ebabaf255a7d16b', E'Cards earlier stays where it is until Julia''s audience read is in.\n\nwhat the memo holds: the audience call and the numbers behind it, with the panel and retention as context.\n\nmemo goes in Julia''s folder with her log note', 140737488519168.0, false, NULL, false, '["793af7ca6940bf18eb516c75"]', '[]', 80, 'qW3nZt7K', NULL, 'https://PERSON_6092_TRELLO_USERNAME.com/c/qW3nZt7K/80-cards-earlier-waiting-on-the-audience-read', '2025-09-30T16:52:31Z', NULL, '{"attachments": 0, "attachmentsByType": {"trello": {"board": 0, "card": 0}}, "checkItems": 0, "checkItemsChecked": 0, "checkItemsEarliestDue": null, "comments": 0, "description": true, "due": null, "dueComplete": false, "externalSource": null, "fogbugz": "", "lastUpdatedByAi": false, "location": false, "maliciousAttachments": 0, "start": null, "votes": 0}');
