INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('2c84150a541063a6138e2f5a0cff9f33', '1758728411.540327', 'C090N54TG79', 'message', 'EMPLOYEE_0038_SLACK_ID', '<@EMPLOYEE_0005_SLACK_ID> <@EMPLOYEE_0016_SLACK_ID> on the feedback note, I wrote up the device and build side in a doc so we all read the friend sessions the same way: ZM session stability gate. shared it with you', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-24T15:40:11.540327Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('7b38bd6429ce0f189456ac72af02f210', '1758729919.603185', 'C090N54TG79', 'message', 'EMPLOYEE_0038_SLACK_ID', 'for the panel it’s stars per player, one number each. if a rating is void it comes out of both the sum and the count, so you average what’s left', 'c53936d63c93c8ffa0ad1e99526cad73', '1758691397.679889', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-24T16:05:19.603185Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('e72083b249987542a134098010edd305', '1758733233.117446', 'C090N54TG79', 'message', 'EMPLOYEE_0038_SLACK_ID', 'One more for the feedback note: game-industry people don’t count, and that goes for sessions already run too. Anyone who works in games plays it like we do, so that’s not the honest reaction I asked for', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-24T17:00:33.117446Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('676eb4bb7c6fde75e63edf27ad453971', '1758818538.552913', 'C090N54TG79', 'message', 'EMPLOYEE_0038_SLACK_ID', 'on the feedback note: friends just means people you know. family, neighbours and old classmates count the same, as long as they’re in the 25–45 band and don’t work in games. that goes for sessions already run too', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-25T16:42:18.552913Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('d7122186e361aa99778c65cb1502759d', '1758819934.612483', 'C090N54TG79', 'message', 'EMPLOYEE_0038_SLACK_ID', 'on watching people play it: careful with android 1943, the one that’s been passed around. it never went through a store, so anyone on it isn’t seeing what a player gets. 0.3.127 (127) on android and 0.3.38 / 0.3.40 on ios all went through the store, those are fine', 'e6a91393854458ad70331ef478952136', '1758581651.167799', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-25T17:05:34.612483Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('167dc58affb9902420038f71d0f5af28', '1758913471.205816', 'D05GU6L0XFH', 'message', 'EMPLOYEE_0016_SLACK_ID', 'Different topic while I''m here, on the friend sessions. If one gets dropped for a technical reason, device or build, put a re-run note on it so the observer runs it again. Dropped for anything else, no re-run, it just gets closed', (SELECT id FROM slack.slack_messages WHERE channel_id = 'D05GU6L0XFH' AND ts = '1758901945.292269'), '1758901945.292269', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-26T19:04:31.205816Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('2ca968ace3e14d1a34c535f8a5c0cd6e', '1759167008.881274', 'C090N54TG79', 'message', 'EMPLOYEE_0016_SLACK_ID', 'On Vincent''s retention post above, when we quote ZM retention let''s use install-weighted D7, not a simple mean of the cohorts. Mature cohorts only, meaning cohorts that have a D14 figure, both platforms pooled. USER_COHORT_RETENTION has what you need', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-29T17:30:08.881274Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('b07f1e10112b7661e1d8eaf3b127227f', '1759266627.418203', 'C090N54TG79', 'message', 'EMPLOYEE_0038_SLACK_ID', E'<@EMPLOYEE_0005_SLACK_ID> I want to settle the cards earlier change from Monday on what players told us, not on our gut. the friend sessions are in your workbook now, so give me one audience call from them: casual, RPG or no clear lead. casual lead means we hold the change. RPG lead means we keep it. no clear lead, we keep it\n\nthe rules I posted in the channel after my note still stand, and how a session gets its audience label and how the lead is read is in the audience read criteria. close the tickets the way your log note says. Robert already told you how not-counted sessions get handled\n\nwhat the memo holds is on the roadmap card. for context use the panel results I forwarded you, and read the panel the way I set out when Robert asked who those players were, plus retention the way Robert set it in the channel after Vincent''s post\n\nreply here with keep or hold, and tell <@EMPLOYEE_0026_SLACK_ID> in this channel whether the tutorial and level order work goes on. this is about the current game only, iterate or pivot is a later call', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T21:10:27.418203Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
